#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/dedicated_supervisor_stop_v27_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/"
cp -a companyos/runtime/service_supervisor.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_v27_patch.py"
python "$PREFIX/tmp/companyos_v27_patch.py"
rm -f "$PREFIX/tmp/companyos_v27_patch.py"

echo "" | base64 -d > scripts/companyos_verify_supervisor_stop_v27
chmod +x scripts/companyos_verify_supervisor_stop_v27

scripts/companyos_verify_supervisor_stop_v27 | tee .companyos_runtime/dedicated_supervisor_stop_v27.log

git add companyos/runtime/runtime_control.py companyos/runtime/service_supervisor.py scripts/companyos_verify_supervisor_stop_v27
git diff --cached --quiet || git commit -m "Isolate supervisor stop channel from child runtime stop file"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "BACKUP=$BK"
echo "COMPANYOS_DEDICATED_SUPERVISOR_STOP_V27=PASS"
